import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";

// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type CryptoChartWidgetProps = Record<string, any>;

// Approximate path data mimicking the ETH chart provided
// Normalized to a 1000x500 viewBox for easier scaling
const CHART_PATH_DATA = `
  M 0 450
  C 20 440, 40 400, 50 350
  L 60 380
  C 70 300, 80 250, 90 200
  L 100 240
  L 110 180
  C 130 180, 150 250, 160 350
  L 170 420
  L 180 480
  L 190 400
  L 200 420
  C 220 380, 240 350, 260 300
  L 270 360
  L 280 320
  L 290 380
  L 300 400
  C 320 350, 340 300, 360 250
  L 370 200
  L 380 150
  C 400 120, 420 80, 440 100
  L 450 120
  L 460 80
  L 470 50
  L 480 80
  L 490 60
  L 500 120
  L 510 180
  L 520 150
  L 530 160
  L 540 200
  L 550 180
  C 580 170, 600 150, 620 140
  L 630 160
  L 640 140
  L 650 100
  L 660 80
  L 670 120
  L 680 100
  L 690 60
  L 700 80
  L 710 100
  L 720 80
  L 730 40
  L 740 60
  L 750 120
  L 760 160
  L 770 100
  L 780 40
  L 790 60
  L 800 20
  L 810 50
  L 820 40
  L 830 80
  L 840 60
  L 850 50
`;

const CryptoChartWidget: React.FC<CryptoChartWidgetProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
  chartColorStart = "#2962FF",
  chartColorEnd = "#D500F9",
  glowColor = "#7C4DFF",
  textColor = "#FFFFFF",
  lineThickness = 4,
  widgetCornerRadius = 24,
  showGrid = true,
}) => {
  useFontLoader(["Inter"]);

  const { fps, width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const containerPadding = 40;
  const chartHeight = height * 0.6;
  const chartWidth = width - containerPadding * 2;

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Progress
  // We want the line to draw over the duration
  const progress = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Use evolvePath to calculate dash array/offset
  // Memoize primarily to avoid recalculating string parsing every render if it were dynamic
  const evolution = useMemo(() => {
    return evolvePath(progress, CHART_PATH_DATA);
  }, [progress]);

  // Fade in text
  const textOpacity = interpolate(
    frame,
    [0, 30],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  // Slide up text
  const textTranslateY = interpolate(
    frame,
    [0, 30],
    [20, 0],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Inter",
      }}
    >
      {/* Widget Container */}
      <div
        style={{
          width: chartWidth,
          height: chartHeight,
          backgroundColor: "#000000", // Inner widget bg is usually dark for charts
          borderRadius: widgetCornerRadius,
          position: "relative",
          overflow: "hidden",
          boxShadow: `0 20px 50px -10px ${glowColor}40`, // Soft glow shadow behind widget
          border: "1px solid #333",
        }}
      >
        {/* Header Text */}
        <div
          style={{
            position: "absolute",
            top: 24,
            left: 32,
            zIndex: 10,
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
          }}
        >
          <h1
            style={{
              margin: 0,
              fontSize: 32,
              fontWeight: 700,
              color: textColor,
              letterSpacing: "-0.5px",
            }}
          >
            ETH<span style={{ color: "#666" }}>/USD</span>
          </h1>
        </div>

        {/* Grid Lines (Optional) */}
        {showGrid && (
          <div style={{ position: "absolute", inset: 0, opacity: 0.1, pointerEvents: "none" }}>
            {Array.from({ length: 5 }).map((_, i) => (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: `${(i + 1) * 16.6}%`,
                  left: 0,
                  right: 0,
                  height: 1,
                  backgroundColor: "#fff",
                }}
              />
            ))}
            {Array.from({ length: 8 }).map((_, i) => (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: `${(i + 1) * 12.5}%`,
                  top: 0,
                  bottom: 0,
                  width: 1,
                  backgroundColor: "#fff",
                }}
              />
            ))}
          </div>
        )}

        {/* Chart SVG */}
        <svg
          viewBox="0 0 1000 500"
          preserveAspectRatio="none"
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            width: "100%",
            height: "80%", // Leave room for header
            overflow: "visible",
          }}
        >
          <defs>
            <linearGradient id="lineGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor={chartColorStart} />
              <stop offset="100%" stopColor={chartColorEnd} />
            </linearGradient>
            
            {/* Glow Filter */}
            <filter id="glow">
              <feGaussianBlur stdDeviation="3.5" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* The Glowing Line Background (Extra intensity) */}
           <path
            d={CHART_PATH_DATA}
            fill="none"
            stroke={glowColor}
            strokeWidth={lineThickness * 3}
            strokeOpacity={0.3}
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            style={{
              filter: "blur(10px)",
              transition: "none",
            }}
          />

          {/* Main Chart Line */}
          <path
            d={CHART_PATH_DATA}
            fill="none"
            stroke="url(#lineGradient)"
            strokeWidth={lineThickness}
            strokeLinecap="round"
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            style={{
              filter: "url(#glow)", // Adds subtle sharpness glow
              transition: "none",
            }}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default CryptoChartWidget;